package com.docgen.pdf

import java.util.concurrent.atomic.{AtomicInteger, AtomicReference}
import java.util.concurrent.{ConcurrentHashMap, Executors, TimeUnit}
import java.io.{File, FileOutputStream, ByteArrayOutputStream}
import scala.concurrent.{Future, ExecutionContext, Promise}
import scala.util.{Try, Success, Failure}

case class PdfRequest(id: String, templateId: String, data: Map[String, String], outputPath: String)
case class PdfResult(id: String, path: String, sizeBytes: Long)

sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(threshold: Int, resetTimeoutMs: Long) {
  private val failureCount = new AtomicInteger(0)
  private val state = new AtomicReference[CircuitState](Closed)
  private val lastFailureTime = new AtomicReference[Long](0L)

  def currentState: CircuitState = {
    val s = state.get()
    if (s == Open && System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
      state.compareAndSet(Open, HalfOpen)
      HalfOpen
    } else s
  }

  def recordSuccess(): Unit = {
    failureCount.set(0)
    state.set(Closed)
  }

  def recordFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= threshold) {
      state.set(Open)
    }
  }

  def isCallPermitted: Boolean = currentState != Open
}

class TemplateCache {
  private val cache = new ConcurrentHashMap[String, Array[Byte]]()
  private val refCounts = new ConcurrentHashMap[String, AtomicInteger]()

  def getOrLoad(templateId: String): Array[Byte] = {
    refCounts.computeIfAbsent(templateId, _ => new AtomicInteger(0)).incrementAndGet()
    cache.computeIfAbsent(templateId, id => loadTemplate(id))
  }

  def release(templateId: String): Unit = {
    val ref = refCounts.get(templateId)
    if (ref != null && ref.decrementAndGet() <= 0) {
      cache.remove(templateId)
      refCounts.remove(templateId)
    }
  }

  private def loadTemplate(id: String): Array[Byte] = {
    val resourcePath = s"/templates/${id}.pdf"
    val stream = getClass.getResourceAsStream(resourcePath)
    if (stream == null) throw new RuntimeException(s"Template not found: $id")
    try {
      val baos = new ByteArrayOutputStream()
      val buf = new Array[Byte](4096)
      var n = stream.read(buf)
      while (n != -1) { baos.write(buf, 0, n); n = stream.read(buf) }
      baos.toByteArray
    } finally stream.close()
  }
}

class PdfGenerationService(maxConcurrent: Int = 4) {
  private val circuitBreaker = new CircuitBreaker(threshold = 5, resetTimeoutMs = 30000)
  private val templateCache = new TemplateCache()
  private val activeJobs = new ConcurrentHashMap[String, PdfRequest]()
  private val completedResults = new ConcurrentHashMap[String, PdfResult]()
  private val executor = Executors.newFixedThreadPool(maxConcurrent)
  implicit val ec: ExecutionContext = ExecutionContext.fromExecutor(executor)

  def generatePdf(request: PdfRequest): Future[PdfResult] = {
    if (!circuitBreaker.isCallPermitted) {
      return Future.failed(new RuntimeException("Circuit breaker is open"))
    }

    val existing = completedResults.get(request.id)
    if (existing != null) return Future.successful(existing)

    activeJobs.put(request.id, request)

    val promise = Promise[PdfResult]()

    Future {
      try {
        val templateBytes = templateCache.getOrLoad(request.templateId)
        val rendered = renderTemplate(templateBytes, request.data)
        val outputFile = writeOutput(request, rendered)
        val result = PdfResult(request.id, outputFile.getAbsolutePath, outputFile.length())
        completedResults.put(request.id, result)
        circuitBreaker.recordSuccess()
        promise.success(result)
      } catch {
        case e: Exception =>
          circuitBreaker.recordFailure()
          promise.failure(e)
      } finally {
        activeJobs.remove(request.id)
        templateCache.release(request.templateId)
      }
    }

    promise.future
  }

  private def renderTemplate(template: Array[Byte], data: Map[String, String]): Array[Byte] = {
    var content = new String(template, "UTF-8")
    data.foreach { case (key, value) =>
      content = content.replace(s"{{$key}}", value)
    }
    content.getBytes("UTF-8")
  }

  private def writeOutput(request: PdfRequest, content: Array[Byte]): File = {
    val outputFile = new File(request.outputPath)
    val tempFile = new File(outputFile.getParent, s".${request.id}.tmp")
    val fos = new FileOutputStream(tempFile)
    try {
      fos.write(content)
      fos.flush()
      fos.getFD.sync()
    } finally fos.close()

    if (!tempFile.renameTo(outputFile)) {
      tempFile.delete()
      throw new RuntimeException(s"Failed to finalize output: ${request.outputPath}")
    }
    outputFile
  }

  def cancelJob(requestId: String): Boolean = {
    val job = activeJobs.remove(requestId)
    if (job != null) {
      templateCache.release(job.templateId)
      true
    } else false
  }

  def getStatus(requestId: String): String = {
    if (completedResults.containsKey(requestId)) "completed"
    else if (activeJobs.containsKey(requestId)) "processing"
    else "unknown"
  }

  def shutdown(): Unit = {
    executor.shutdown()
    executor.awaitTermination(30, TimeUnit.SECONDS)
  }
}
